#include <iostream>
#include <string>
#include <vector>

class UndoText
{
public:
    void type(const std::string& s) {}
    void undo() {}
    void redo() {}
    const std::string& text() const { return m_text; }

private:
    std::string m_text{};
    std::vector<std::string> m_undo{}, m_redo{};
    bool m_grouping{false};
};

int main()
{
    UndoText t{};
    t.type("Hello");
    std::cout << t.text() << '\n';
}
